module MomentHelperTest # a module makes it easier to do some changes in the same Julia session, as this contains lots of constants

using Test, PolynomialOptimization.Solver, LinearAlgebra
using PolynomialOptimization.Solver: PSDIndextype

const sqrt2 = sqrt(Float32(2))
Base.://(x::Number, y::Float32) = inv(y) * x

function checkequality(indvals::Indvals{I,V}, supposed_indices::AbstractVector{I}, supposed_values::AbstractVector{V}) where {I,V}
    # we don't have any guarantee that the indices are ordered, and we must keep their order
    indices, values = indvals.indices, indvals.values
    # sometimes, cancellations may happen that will give rise to explicit zeros, but the test code generation will have them dropped
    keeppos_unsorted = findall(!iszero, values)
    @views keeppos = keeppos_unsorted[sortperm(indices[keeppos_unsorted])]
    return @views indices[keeppos] == supposed_indices && isapprox(values[keeppos], supposed_values, atol=1e-13)
end

function checkequality(indvals::IndvalsIterator{I,V}, (supposed_indices, supposed_values, supposed_lens)::Tuple{AbstractVector{I},AbstractVector{V},AbstractVector{Int}}) where {I,V}
    i = 0
    ri = 1
    for indval in indvals
        keeppos_unsorted = findall(!iszero, indval.values)
        if isempty(keeppos_unsorted)
            length(supposed_lens) > i && iszero(supposed_lens[i+1]) && (i += 1)
            continue
        end
        i += 1
        len = supposed_lens[i]
        @views s_ind, s_val = supposed_indices[ri:ri+len-1], supposed_values[ri:ri+len-1]
        ri += len
        @views keeppos = keeppos_unsorted[sortperm(indval.indices[keeppos_unsorted])]
        @test @views indval.indices[keeppos] == s_ind && isapprox(indval.values[keeppos], s_val, atol=1e-13)
    end
    @test i == length(supposed_lens)
end

function checkequality(data::PSDMatrixCartesian{I,V}, ::Val{tri}, (mons, rows, cols, vals, lens)::Tuple{Vector{I},Vector{Int},Vector{Int},Vector{V},Vector{Int}}) where {tri,I,V}
    i = 0
    ri = 1
    for (mon, (row, col, val)) in data
        all(iszero, val) && continue # it may rarely happen that we end up with an all-zeros entry, which would not be present in the test
        i += 1
        @test mon == mons[i]
        len = lens[i]
        if tri !== :L
            @views vals[ri:ri+len-1] .= conj.(vals[ri:ri+len-1])
        end
        rg = ri:ri+len-1
        sort_along!(row, col, val, relevant=2)
        keeppos = findall(!iszero, val)
        supposed_rows = @view(rows[rg])
        supposed_cols = @view(cols[rg])
        supposed_values = @view(vals[rg])
        sort_along!(supposed_rows, supposed_cols, supposed_values, relevant=2)
        @test @views row[keeppos] == supposed_rows && col[keeppos] == supposed_cols && isapprox(val[keeppos], supposed_values, atol=1e-13)
        ri += len
    end
    @test i == length(mons)
end

abstract type AbstractSolverSetup <: Solver.AbstractSolver{BigInt,Float32} end

mutable struct MomentSolverSetup{Linear,Quadratic,RQuadratic,PSD,Complex,Fixed} <: AbstractSolverSetup
    const instance::Int
    lastcall::Symbol
    it::Int
    const fixed_available::Set{UInt}

    function MomentSolverSetup(instance::Int; linear::Bool=false, quadratic::Bool=false, rquadratic::Bool=false,
        psd::Union{Bool,<:PSDIndextype}=false, complex::Bool=false, fixed::Bool=false)
        @assert psd !== true
        new{linear,quadratic,rquadratic,psd,complex,fixed}(instance, :none, 0, Set{UInt}())
    end
end

mutable struct SOSSolverSetup{Linear,Quadratic,RQuadratic,DD,L1,SDD,Complex} <: AbstractSolverSetup
    const instance::Int
    lastcall::Symbol
    it::Int
    const representation::Solver.RepresentationMethod
    const free_available::Set{UInt}
    
    function SOSSolverSetup(instance::Int; linear::Bool=false, quadratic::Bool=false, rquadratic::Bool=false,
        dd::Union{Bool,<:PSDIndextype}=false, l1::Bool=false, sdd::Union{Bool,<:PSDIndextype}=false, complex::Bool=false,
        representation::Solver.RepresentationMethod)
        new{linear,quadratic,rquadratic,dd,l1,sdd,complex}(instance, :none, 0, representation, Set{UInt}())
    end
end

Solver.mindex(::AbstractSolverSetup, monomials::IntMonomialOrConj...) = BigInt(monomial_index(monomials...) + 48)

Solver.supports_quadratic(        ::MomentSolverSetup{<:Any,s              }) where {s} = s
Solver.supports_rotated_quadratic(::MomentSolverSetup{<:Any,<:Any,s        }) where {s} = s
Solver.supports_psd_complex(      ::MomentSolverSetup{<:Any,<:Any,<:Any,s,c}) where {s,c} = s !== false && c
Solver.psd_indextype(::MomentSolverSetup{<:Any,<:Any,<:Any,psd}) where {psd} = psd
Solver.psd_indextype(::MomentSolverSetup{<:Any,<:Any,<:Any,false}) = PSDIndextypeMatrixCartesian(:U, typemin(Int)) # should only be triggered for linear/quadratic case, and then the offset is ignored
Solver.psd_indextype(::SOSSolverSetup{<:Any,<:Any,<:Any,psd,<:Any,false}) where {psd} = psd
Solver.psd_indextype(::SOSSolverSetup{<:Any,<:Any,<:Any,false,<:Any,psd}) where {psd} = psd
Solver.psd_indextype(::SOSSolverSetup{<:Any,<:Any,<:Any,false,<:Any,false}) = PSDIndextypeMatrixCartesian(:U, typemin(Int))

Solver.supports_quadratic(        ::SOSSolverSetup{<:Any,s                              }) where {s} = s
Solver.supports_rotated_quadratic(::SOSSolverSetup{<:Any,<:Any,s                        }) where {s} = s
Solver.supports_dd(               ::SOSSolverSetup{<:Any,<:Any,<:Any,s                  }) where {s} = s !== false
Solver.supports_dd_complex(       ::SOSSolverSetup{<:Any,<:Any,<:Any,s,    <:Any,<:Any,c}) where {s,c} = s !== false && c
Solver.supports_lnorm(            ::SOSSolverSetup{<:Any,<:Any,<:Any,<:Any,s            }) where {s} = s
Solver.supports_lnorm_complex(    ::SOSSolverSetup{<:Any,<:Any,<:Any,<:Any,s,    <:Any,c}) where {s,c} = s && c
Solver.supports_sdd(              ::SOSSolverSetup{<:Any,<:Any,<:Any,<:Any,<:Any,s      }) where {s} = s !== false
Solver.supports_sdd_complex(      ::SOSSolverSetup{<:Any,<:Any,<:Any,<:Any,<:Any,s,    c}) where {s,c} = s !== false && c

function momenttest(instance, grouping, constraint, type)
    if type === :moment_linear
        states = (MomentSolverSetup(instance, linear=true),)
    elseif type === :moment_quadratic
        states = (MomentSolverSetup(instance, quadratic=true),)
    elseif type === :moment_rquadratic
        states = (MomentSolverSetup(instance, rquadratic=true),)
    elseif type === :moment_psdr
        states = (MomentSolverSetup(instance, psd=PSDIndextypeVector(:L, sqrt2)),
                  MomentSolverSetup(instance, psd=PSDIndextypeVector(:U, sqrt2)),
                  MomentSolverSetup(instance, psd=PSDIndextypeVector(:F)),
                  MomentSolverSetup(instance, psd=PSDIndextypeMatrixCartesian(:L, 17)),
                  MomentSolverSetup(instance, psd=PSDIndextypeMatrixCartesian(:U, 17)))
    elseif type === :moment_psdc
        states = (MomentSolverSetup(instance, psd=PSDIndextypeVector(:L, sqrt2), complex=true),
                  MomentSolverSetup(instance, psd=PSDIndextypeVector(:U, sqrt2), complex=true),
                  MomentSolverSetup(instance, psd=PSDIndextypeVector(:F), complex=true),
                  MomentSolverSetup(instance, psd=PSDIndextypeMatrixCartesian(:L, 17), complex=true),
                  MomentSolverSetup(instance, psd=PSDIndextypeMatrixCartesian(:U, 17), complex=true))
    elseif type === :moment_equality
        state = MomentSolverSetup(instance, fixed=true)
        moment_add_equality!(state, [grouping], constraint)
        @test state.lastcall === :add_constr_fix_finalize
        return
    else
        @assert(false)
    end
    for state in states
        moment_add_matrix!(state, grouping, constraint)
        @test state.lastcall === type
    end
    return
end

function sostest(instance, grouping, constraint, type)
    ud = Diagonal(1:100)
    uf = reshape(1:100^2, 100, 100)
    udc = Diagonal(reinterpret(reshape, Complex{Int}, reshape(1:200, 2, 100)))
    ufc = reinterpret(reshape, Complex{Int}, reshape(1:2*100^2, 2, 100, 100))
    if type === :sos_ddr
        states = (SOSSolverSetup(instance; dd=PSDIndextypeVector(:U, sqrt2), complex=true, representation=Solver.RepresentationDD(complex=false)),
                  SOSSolverSetup(instance; l1=true, representation=Solver.RepresentationDD()),
                  SOSSolverSetup(instance; linear=true, representation=Solver.RepresentationDD()),

                  SOSSolverSetup(instance +1; l1=true, representation=Solver.RepresentationDD(ud)),
                  SOSSolverSetup(instance +1; linear=true, representation=Solver.RepresentationDD(ud)),

                  SOSSolverSetup(instance +2; l1=true, representation=Solver.RepresentationDD(uf)),
                  SOSSolverSetup(instance +2; linear=true, representation=Solver.RepresentationDD(uf)),

                  SOSSolverSetup(instance +3; l1=true, representation=Solver.RepresentationDD(UpperTriangular(uf))),
                  SOSSolverSetup(instance +3; linear=true, representation=Solver.RepresentationDD(UpperTriangular(uf))),
                  SOSSolverSetup(instance +4; l1=true, representation=Solver.RepresentationDD(LowerTriangular(uf))),
                  SOSSolverSetup(instance +4; linear=true, representation=Solver.RepresentationDD(LowerTriangular(uf))))
    elseif type === :sos_ddc
        states = (SOSSolverSetup(instance; dd=PSDIndextypeVector(:U, sqrt2), complex=true, representation=Solver.RepresentationDD()),
                  SOSSolverSetup(instance; l1=true, complex=true, representation=Solver.RepresentationDD()),
                  SOSSolverSetup(instance; quadratic=true, representation=Solver.RepresentationDD()),

                  SOSSolverSetup(instance +1; l1=true, complex=true, representation=Solver.RepresentationDD(udc)),
                  SOSSolverSetup(instance +1; quadratic=true, representation=Solver.RepresentationDD(udc)),
                  
                  SOSSolverSetup(instance +2; l1=true, complex=true, representation=Solver.RepresentationDD(ufc)),
                  SOSSolverSetup(instance +2; quadratic=true, representation=Solver.RepresentationDD(ufc)),

                  SOSSolverSetup(instance +3; l1=true, complex=true, representation=Solver.RepresentationDD(UpperTriangular(ufc))),
                  SOSSolverSetup(instance +3; quadratic=true, representation=Solver.RepresentationDD(UpperTriangular(ufc))),
                  SOSSolverSetup(instance +4; l1=true, complex=true, representation=Solver.RepresentationDD(LowerTriangular(ufc))),
                  SOSSolverSetup(instance +4; quadratic=true, representation=Solver.RepresentationDD(LowerTriangular(ufc))))
    elseif type === :sos_sddr
        states = (SOSSolverSetup(instance, sdd=PSDIndextypeVector(:U, sqrt2), representation=Solver.RepresentationSDD(complex=false)),
                  SOSSolverSetup(instance, rquadratic=true, representation=Solver.RepresentationSDD(complex=false)),
                  SOSSolverSetup(instance, quadratic=true, representation=Solver.RepresentationSDD(complex=false)),

                  SOSSolverSetup(instance +1, rquadratic=true, representation=Solver.RepresentationSDD(ud, complex=false)),
                  SOSSolverSetup(instance +1, quadratic=true, representation=Solver.RepresentationSDD(ud, complex=false)),

                  SOSSolverSetup(instance +2, rquadratic=true, representation=Solver.RepresentationSDD(uf, complex=false)),
                  SOSSolverSetup(instance +2, quadratic=true, representation=Solver.RepresentationSDD(uf, complex=false)),

                  SOSSolverSetup(instance +3, rquadratic=true, representation=Solver.RepresentationSDD(UpperTriangular(uf), complex=false)),
                  SOSSolverSetup(instance +3, quadratic=true, representation=Solver.RepresentationSDD(UpperTriangular(uf), complex=false)),
                  SOSSolverSetup(instance +4, rquadratic=true, representation=Solver.RepresentationSDD(LowerTriangular(uf), complex=false)),
                  SOSSolverSetup(instance +4, quadratic=true, representation=Solver.RepresentationSDD(LowerTriangular(uf), complex=false)))
    elseif type === :sos_sddc
        states = (SOSSolverSetup(instance, sdd=PSDIndextypeVector(:U, sqrt2), complex=true, representation=Solver.RepresentationSDD()),
                  SOSSolverSetup(instance, rquadratic=true, complex=true, representation=Solver.RepresentationSDD()),
                  SOSSolverSetup(instance, quadratic=true, complex=true, representation=Solver.RepresentationSDD()),

                  SOSSolverSetup(instance +1, rquadratic=true, complex=true, representation=Solver.RepresentationSDD(udc)),
                  SOSSolverSetup(instance +1, quadratic=true, complex=true, representation=Solver.RepresentationSDD(udc)),

                  SOSSolverSetup(instance +2, rquadratic=true, complex=true, representation=Solver.RepresentationSDD(ufc)),
                  SOSSolverSetup(instance +2, quadratic=true, complex=true, representation=Solver.RepresentationSDD(ufc)),

                  SOSSolverSetup(instance +3, rquadratic=true, complex=true, representation=Solver.RepresentationSDD(UpperTriangular(ufc))),
                  SOSSolverSetup(instance +3, quadratic=true, complex=true, representation=Solver.RepresentationSDD(UpperTriangular(ufc))),
                  SOSSolverSetup(instance +4, rquadratic=true, complex=true, representation=Solver.RepresentationSDD(LowerTriangular(ufc))),
                  SOSSolverSetup(instance +4, quadratic=true, complex=true, representation=Solver.RepresentationSDD(LowerTriangular(ufc))))
    else
        @assert(false)
    end
    for state in states
        sos_add_matrix!(state, grouping, constraint, state.representation)
        @test state.lastcall === type
    end
    return
end

Solver.add_constr_psd!(state, dim, data) = add_constr_psd_worker!(state, dim, psd_indextype(state), data)

Solver.add_constr_psd_complex!(state, dim, data) = add_constr_psd_complex_worker!(state, dim, psd_indextype(state), data)

Solver.add_var_dd!(state, dim, data, u) = add_var_dd_worker!(state, dim, psd_indextype(state), data, u)

Solver.add_var_dd_complex!(state, dim, data, u) = add_var_dd_complex_worker!(state, dim, psd_indextype(state), data, u)

Solver.add_var_sdd!(state, dim, data, u) = add_var_sdd_worker!(state, dim, psd_indextype(state), data, u)

Solver.add_var_sdd_complex!(state, dim, data, u) = add_var_sdd_complex_worker!(state, dim, psd_indextype(state), data, u)

