function Solver.add_constr_nonnegative!(state::MomentSolverSetup{true,false,false,false,false,false}, indvals::Indvals{BigInt,Float32})
    @test state.lastcall === :none
    state.lastcall = :moment_linear
    @test checkequality(indvals, ADD_CONSTR_NONNEGATIVE[state.instance]...)
end

