function add_constr_psd_complex_worker!(state::MomentSolverSetup{false,false,false,<:Any,true,false}, dim::Int, ::PSDIndextypeMatrixCartesian{tri,17}, data::PSDMatrixCartesian{BigInt,Complex{Float32}}) where {tri}
    @test state.lastcall === :none
    state.lastcall = :moment_psdc
    ref_id, ref_row, ref_col, ref_val, ref_len = ADD_CONSTR_PSDCM[state.instance]
    checkequality(data, Val(tri), (ref_id, tri === :L ? ref_row : ref_col, tri === :L ? ref_col : ref_row, ref_val, ref_len))
end

