function Solver.add_constr_fix_prepare!(state::MomentSolverSetup{false,false,false,false,false,true}, num::Int)
    @test state.lastcall === :none
    @test isempty(state.fixed_available)
    state.lastcall = :add_constr_fix_prepare
    union!(state.fixed_available, UInt(1):UInt(num))
    return UInt(num)
end

function Solver.add_constr_fix_finalize!(state::MomentSolverSetup{false,false,false,false,false,true}, constrstate::UInt)
    @test state.lastcall === :add_constr_fix
    state.lastcall = :add_constr_fix_finalize
    @test iszero(constrstate)
    @test isempty(state.fixed_available)
end

function Solver.add_constr_fix!(state::MomentSolverSetup{false,false,false,false,false,true}, constrstate::UInt, indvals::Indvals{BigInt,Float32}, rhs::Float32)
    @test in(state.lastcall, (:add_constr_fix_prepare, :add_constr_fix))
    state.lastcall = :add_constr_fix
    @test iszero(rhs)

    ref_indices, ref_values, ref_lens = ADD_CONSTR_FIX[state.instance]
    rg = 0:0
    for (i, len) in enumerate(ref_lens)
        rg = last(rg)+1:last(rg)+len
        if len <= length(indvals) && UInt(i) in state.fixed_available && @views(checkequality(indvals, ref_indices[rg], ref_values[rg]))
            pop!(state.fixed_available, UInt(i))
            return constrstate - one(UInt)
        end
    end
    @test false
end

