function Solver.add_var_quadratic!(state::SOSSolverSetup{false,true,false,false,false,false,complex}, indvals::IndvalsIterator{BigInt,Float32}) where {complex}
    if iszero(state.it)
        @test state.lastcall === :add_var_free_finalize
        if state.instance in (181,182,183,184,185,193,194,195,196,197,205,206,207,208,209,217,218,219,220,221)
            state.lastcall = :sos_ddc
        else
            state.lastcall = complex ? :sos_sddc : :sos_sddr
        end
    else
        @test (complex ? state.lastcall === :sos_sddc : state.lastcall in (:sos_ddc, :sos_sddr))
    end
    checkequality(indvals, ADD_VAR_DDQ[state.instance][state.it+=1])
end

