function Solver.add_var_rotated_quadratic!(state::SOSSolverSetup{false,false,true,false,false,false,complex}, indvals::IndvalsIterator{BigInt,Float32}) where {complex}
    @test state.lastcall === (iszero(state.it) ? :add_var_free_finalize : (complex ? :sos_sddc : :sos_sddr))
    state.lastcall = complex ? :sos_sddc : :sos_sddr
    checkequality(indvals, ADD_VAR_SDDRQ[state.instance][state.it+=1])
end

end

using Test, PolynomialOptimization.IntPolynomials

@testset failfast=true verbose=true "Moment helpers" begin
    # the grouping is {1}
    @testset let grouping=IntMonomialVector{4,2}(UInt[1])
        # the constraint is 6x₁
        @testset let constraint=IntPolynomial(Float32[6], IntMonomialVector{4,2}(UInt[9]))
            MomentHelperTest.momenttest(235, grouping, constraint, :moment_equality)
            MomentHelperTest.momenttest(240, grouping, constraint, :moment_equality)
        end
        # the constraint is (6 + 4I)z₁
        @testset let constraint=IntPolynomial(Complex{Float32}[6+4im], IntMonomialVector{4,2}(UInt[5]))
            MomentHelperTest.momenttest(237, grouping, constraint, :moment_equality)
            MomentHelperTest.momenttest(242, grouping, constraint, :moment_equality)
        end
        # the constraint is (6 + 4I)z₁ + (6 - 4I)z̄₁
        @testset let constraint=IntPolynomial(Complex{Float32}[6-4im,6+4im], IntMonomialVector{4,2}(UInt[4, 5]))
            MomentHelperTest.momenttest(236, grouping, constraint, :moment_equality)
            MomentHelperTest.momenttest(241, grouping, constraint, :moment_equality)
        end
        # the constraint is (2I)x₃ + (6 + 4I)z₁ + 8z̄₁
        @testset let constraint=IntPolynomial(Complex{Float32}[8,6+4im,2im], IntMonomialVector{4,2}(UInt[4, 5, 7]))
            MomentHelperTest.momenttest(238, grouping, constraint, :moment_equality)
            MomentHelperTest.momenttest(243, grouping, constraint, :moment_equality)
        end
        # the constraint is -10 - 2z₂² + 8z₂z̄₂ - 2z̄₂²
        @testset let constraint=IntPolynomial(Float32[-10,-2,8,-2], IntMonomialVector{4,2}(UInt[1, 10, 11, 12]))
            MomentHelperTest.momenttest(239, grouping, constraint, :moment_equality)
            MomentHelperTest.momenttest(244, grouping, constraint, :moment_equality)
        end
    end

    # the grouping is {x₂²x₃}
    @testset let grouping=IntMonomialVector{4,2}(UInt[128])
        # the constraint is 2x₁ + 8x₂x₄²
        @testset let constraint=IntPolynomial(Float32[2,8], IntMonomialVector{4,2}(UInt[9, 116]))
            MomentHelperTest.momenttest(3, grouping, constraint, :moment_linear)
        end
        # the constraint is 3(z₁ + z̄₁)
        @testset let constraint=IntPolynomial(Float32[3,3], IntMonomialVector{4,2}(UInt[4, 5]))
            MomentHelperTest.momenttest(4, grouping, constraint, :moment_linear)
        end
        # the constraint is (7I)(-(z₂²z̄₁) + z₁z̄₂²)
        @testset let constraint=IntPolynomial(Complex{Float32}[-7im,7im], IntMonomialVector{4,2}(UInt[52, 56]))
            MomentHelperTest.momenttest(5, grouping, constraint, :moment_linear)
        end
        # the constraint is 17x₁x₃²
        @testset let constraint=IntPolynomial(Float32[17], IntMonomialVector{4,2}(UInt[150]))
            MomentHelperTest.momenttest(1, grouping, constraint, :moment_linear)
        end
        # the constraint is 24x₂z₁z̄₁
        @testset let constraint=IntPolynomial(Float32[24], IntMonomialVector{4,2}(UInt[110]))
            MomentHelperTest.momenttest(2, grouping, constraint, :moment_linear)
        end
        # the constraint is 3x₁ + 5x₂x₄² + (4 + 8I)z₁ + (4 - 8I)z̄₁ + 4z₂z̄₂ + 7(z₂z̄₁² + z₁²z̄₂)
        @testset let constraint=IntPolynomial(Complex{Float32}[4-8im,4+8im,3,4,7,7,5], IntMonomialVector{4,2}(UInt[4, 5, 9, 11, 54, 62, 116]))
            MomentHelperTest.momenttest(6, grouping, constraint, :moment_linear)
        end
    end

    # the grouping is {x₂²z₁}
    @testset let grouping=IntMonomialVector{4,2}(UInt[126])
        # the constraint is 2x₁ + 8x₂x₄²
        @testset let constraint=IntPolynomial(Float32[2,8], IntMonomialVector{4,2}(UInt[9, 116]))
            MomentHelperTest.momenttest(9, grouping, constraint, :moment_linear)
        end
        # the constraint is 3(z₁ + z̄₁)
        @testset let constraint=IntPolynomial(Float32[3,3], IntMonomialVector{4,2}(UInt[4, 5]))
            MomentHelperTest.momenttest(10, grouping, constraint, :moment_linear)
        end
        # the constraint is (7I)(-(z₂²z̄₁) + z₁z̄₂²)
        @testset let constraint=IntPolynomial(Complex{Float32}[-7im,7im], IntMonomialVector{4,2}(UInt[52, 56]))
            MomentHelperTest.momenttest(11, grouping, constraint, :moment_linear)
        end
        # the constraint is 17x₁x₃²
        @testset let constraint=IntPolynomial(Float32[17], IntMonomialVector{4,2}(UInt[150]))
            MomentHelperTest.momenttest(7, grouping, constraint, :moment_linear)
        end
        # the constraint is 24x₂z₁z̄₁
        @testset let constraint=IntPolynomial(Float32[24], IntMonomialVector{4,2}(UInt[110]))
            MomentHelperTest.momenttest(8, grouping, constraint, :moment_linear)
        end
        # the constraint is 3x₁ + 5x₂x₄² + (4 + 8I)z₁ + (4 - 8I)z̄₁ + 4z₂z̄₂ + 7(z₂z̄₁² + z₁²z̄₂)
        @testset let constraint=IntPolynomial(Complex{Float32}[4-8im,4+8im,3,4,7,7,5], IntMonomialVector{4,2}(UInt[4, 5, 9, 11, 54, 62, 116]))
            MomentHelperTest.momenttest(12, grouping, constraint, :moment_linear)
        end
    end

    # the grouping is {x₂²z₂}
    @testset let grouping=IntMonomialVector{4,2}(UInt[124])
        # the constraint is {{17x₃²z₁z̄₁, (8I)x₂²}, {(-8I)x₂², 6x₂x₄²}}
        @testset let constraint=[IntPolynomial(Complex{Float32}[17], IntMonomialVector{4,2}(UInt[279])) IntPolynomial(Complex{Float32}[8im], IntMonomialVector{4,2}(UInt[37])); IntPolynomial(Complex{Float32}[-8im], IntMonomialVector{4,2}(UInt[37])) IntPolynomial(Complex{Float32}[6], IntMonomialVector{4,2}(UInt[116]))]
            MomentHelperTest.momenttest(134, grouping, constraint, :moment_quadratic)
            MomentHelperTest.momenttest(135, grouping, constraint, :moment_rquadratic)
            MomentHelperTest.momenttest(136, grouping, constraint, :moment_psdr)
            MomentHelperTest.momenttest(137, grouping, constraint, :moment_psdc)
        end
        # the constraint is {{17x₃²z₁z̄₁, 8x₂²}, {8x₂², 6x₂x₄²}}
        @testset let constraint=[IntPolynomial(Float32[17], IntMonomialVector{4,2}(UInt[279])) IntPolynomial(Float32[8], IntMonomialVector{4,2}(UInt[37])); IntPolynomial(Float32[8], IntMonomialVector{4,2}(UInt[37])) IntPolynomial(Float32[6], IntMonomialVector{4,2}(UInt[116]))]
            MomentHelperTest.momenttest(131, grouping, constraint, :moment_quadratic)
            MomentHelperTest.momenttest(132, grouping, constraint, :moment_rquadratic)
            MomentHelperTest.momenttest(133, grouping, constraint, :moment_psdr)
        end
        # the constraint is {{17x₃²z₁z̄₁, (8I)z₂²}, {(-8I)z̄₂², 6x₂x₄²}}
        @testset let constraint=[IntPolynomial(Complex{Float32}[17], IntMonomialVector{4,2}(UInt[279])) IntPolynomial(Complex{Float32}[8im], IntMonomialVector{4,2}(UInt[12])); IntPolynomial(Complex{Float32}[-8im], IntMonomialVector{4,2}(UInt[10])) IntPolynomial(Complex{Float32}[6], IntMonomialVector{4,2}(UInt[116]))]
            MomentHelperTest.momenttest(142, grouping, constraint, :moment_quadratic)
            MomentHelperTest.momenttest(143, grouping, constraint, :moment_rquadratic)
            MomentHelperTest.momenttest(144, grouping, constraint, :moment_psdr)
            MomentHelperTest.momenttest(145, grouping, constraint, :moment_psdc)
        end
        # the constraint is {{17x₃²z₁z̄₁, 8z₂²}, {8z̄₂², 6x₂x₄²}}
        @testset let constraint=[IntPolynomial(Float32[17], IntMonomialVector{4,2}(UInt[279])) IntPolynomial(Float32[8], IntMonomialVector{4,2}(UInt[12])); IntPolynomial(Float32[8], IntMonomialVector{4,2}(UInt[10])) IntPolynomial(Float32[6], IntMonomialVector{4,2}(UInt[116]))]
            MomentHelperTest.momenttest(138, grouping, constraint, :moment_quadratic)
            MomentHelperTest.momenttest(139, grouping, constraint, :moment_rquadratic)
