        @testset let constraint=IntPolynomial(Float32[3,3], IntMonomialVector{4,2}(UInt[4, 5]))
            MomentHelperTest.momenttest(88, grouping, constraint, :moment_psdr)
            MomentHelperTest.sostest(89, grouping, constraint, :sos_ddr)
            MomentHelperTest.sostest(94, grouping, constraint, :sos_sddr)
        end
        # the constraint is (7I)(-(z₂²z̄₁) + z₁z̄₂²)
        @testset let constraint=IntPolynomial(Complex{Float32}[-7im,7im], IntMonomialVector{4,2}(UInt[52, 56]))
            MomentHelperTest.momenttest(99, grouping, constraint, :moment_psdr)
            MomentHelperTest.sostest(100, grouping, constraint, :sos_ddr)
            MomentHelperTest.sostest(105, grouping, constraint, :sos_sddr)
        end
        # the constraint is 17x₁x₃²
        @testset let constraint=IntPolynomial(Float32[17], IntMonomialVector{4,2}(UInt[150]))
            MomentHelperTest.momenttest(55, grouping, constraint, :moment_psdr)
            MomentHelperTest.sostest(56, grouping, constraint, :sos_ddr)
            MomentHelperTest.sostest(61, grouping, constraint, :sos_sddr)
        end
        # the constraint is 24x₂z₁z̄₁
        @testset let constraint=IntPolynomial(Float32[24], IntMonomialVector{4,2}(UInt[110]))
            MomentHelperTest.momenttest(66, grouping, constraint, :moment_psdr)
            MomentHelperTest.sostest(67, grouping, constraint, :sos_ddr)
            MomentHelperTest.sostest(72, grouping, constraint, :sos_sddr)
        end
        # the constraint is 3x₁ + 5x₂x₄² + (4 + 8I)z₁ + (4 - 8I)z̄₁ + 4z₂z̄₂ + 7(z₂z̄₁² + z₁²z̄₂)
        @testset let constraint=IntPolynomial(Complex{Float32}[4-8im,4+8im,3,4,7,7,5], IntMonomialVector{4,2}(UInt[4, 5, 9, 11, 54, 62, 116]))
            MomentHelperTest.momenttest(110, grouping, constraint, :moment_psdr)
            MomentHelperTest.sostest(111, grouping, constraint, :sos_ddr)
            MomentHelperTest.sostest(116, grouping, constraint, :sos_sddr)
        end
    end

    # the grouping is {1, x₂, x₁, x₂², x₁x₂, x₁²}
    @testset let grouping=IntMonomialVector{4,2}(UInt[1, 8, 9, 37, 44, 45])
        # the constraint is 5x₁
        @testset let constraint=IntPolynomial(Float32[5], IntMonomialVector{4,2}(UInt[9]))
            MomentHelperTest.momenttest(255, grouping, constraint, :moment_equality)
        end
        # the constraint is (6 + 8I)z̄₁
        @testset let constraint=IntPolynomial(Complex{Float32}[6+8im], IntMonomialVector{4,2}(UInt[4]))
            MomentHelperTest.momenttest(257, grouping, constraint, :moment_equality)
        end
        # the constraint is (6 - 8I)z₁ + (6 + 8I)z̄₁
        @testset let constraint=IntPolynomial(Complex{Float32}[6+8im,6-8im], IntMonomialVector{4,2}(UInt[4, 5]))
            MomentHelperTest.momenttest(256, grouping, constraint, :moment_equality)
        end
    end
end